  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Claude y ChatGPT inician sesión con tu cuenta de Memora. No hay nada que copiar.",
  "Claude models": "Modelos de Claude",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude inicia sesión por OAuth, así que no se pega ninguna clave: recibe la suya al pulsar Permitir. Sin inicio de sesión, conéctalo como <b>Otra app</b> y envía la cabecera <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor y más",
