  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "Arrastra una tarjeta a otro marco de carpeta para mover la nota en el disco. Arrastra un marco por su nombre para reorganizar el tablero; suéltalo sobre otro marco para mover allí toda la carpeta. Doble clic en un título para renombrar. En pantalla táctil: arrastra para desplazar, pellizca para hacer zoom, mantén pulsada una tarjeta para moverla, toca para previsualizar.",
  "Drag a note here to pin it": "Arrastra una nota aquí para fijarla",
  "Drag notes or folders here to pin them": "Arrastra notas o carpetas aquí para fijarlas",
  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "Arrastra notas o carpetas sobre una carpeta para moverlas, o sobre Fijados para fijarlas.",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "Arrastra notas · doble clic para fijar · / buscar · #etiqueta busca etiquetas · F ajustar · 1 2 3 diseños",
  "Drag to move the folder frame; double-click to rename": "Arrastra para mover el marco de la carpeta; doble clic para renombrar",
  "Drag to move the lane. Double click the name to rename it.": "Arrastra para mover la columna. Haz doble clic en el nombre para renombrarla.",
  "Drag to resize · double-click to reset": "Arrastra para cambiar el tamaño · doble clic para restablecer",
  "Drag to turn · scroll to zoom · click a point to open its note": "Arrastra para girar · desplaza para hacer zoom · haz clic en un punto para abrir su nota",
  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "Arrastra para girar · desplaza para hacer zoom · haz clic en un punto para abrir su nota · / para buscar · #etiqueta busca etiquetas",
