  "Each AI app connects over MCP with its own key and permissions.": "Cada app de IA se conecta por MCP con su propia clave y permisos.",
  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "Cada app de IA que conectas es un agente con su propia clave, así ves lo que hace cada una y puedes desactivar una por separado.",
  "Each agent": "Cada agente",
  "Each agent belongs to one app. For another app or device, make a new agent.": "Cada agente pertenece a una app. Para otra app o dispositivo, crea un agente nuevo.",
  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "Cada agente pertenece a una app. Para usar Memora en otra app, crea un agente aparte.",
  "Each app gets its own key": "Cada app tiene su propia clave",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "Cada uno tiene un id corto que nunca cambia, así que los nombres pueden cambiar libremente. Mnemo los prepara, cambia sus instrucciones o su modelo, les escribe, los espera, los detiene, los da por terminados y los quita, de uno en uno o todos a la vez, y puede dejarlos trabajar en segundo plano. Cada tarjeta muestra Instrucción, Actividad y Respuesta.",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "Cada tipo se mide según su propio espacio: su límite si lo hay, o si no lo que usa más el espacio libre en disco{disk}. Límite vacío: sin límite.",
  "Each one gets its own key from Memora.": "Cada uno recibe su propia clave de Memora.",
