  "Every action, newest first, with search and filters.": "Cada acción, la más reciente primero, con búsqueda y filtros.",
  "Every address from one to another.": "Todas las direcciones de una a otra.",
  "Every address from the first to the last, joined by a dash.": "Todas las direcciones de la primera a la última, unidas por un guion.",
  "Every agent usually starts from zero. {bold} connect each agent once and they all read the same vault and write back to it, so what one learns, the others can use.": "Cada agente suele empezar de cero. {bold} conecta cada agente una vez y todos leen la misma bóveda y escriben en ella, así lo que uno aprende, los demás lo pueden usar.",
  "Every board with its lanes and progress. New board sits wherever New note does: the sidebar, Overview, folders, menus, search and the B key.": "Cada tablero con sus columnas y su progreso. Nuevo tablero está dondequiera que esté Nueva nota: la barra lateral, Resumen, las carpetas, los menús, la búsqueda y la tecla B.",
  "Every browser and agent is disconnected until someone starts Memora again on that machine. This page cannot start it again.": "Todos los navegadores y agentes se desconectan hasta que alguien vuelva a iniciar Memora en esa máquina. Esta página no puede iniciarla de nuevo.",
  "Every call shows up live in the brain and Activity": "Cada llamada aparece al instante en el cerebro y en Actividad",
  "Every change Mnemo makes shows in Activity and can be undone from History.": "Cada cambio que hace Mnemo aparece en Actividad y se puede deshacer desde el Historial.",
  "Every change, by you or an app, shows in Activity and can be undone from History.": "Cada cambio, tuyo o de una app, aparece en Actividad y se puede deshacer desde el Historial.",
  "Every chat is archived.": "Todos los chats están archivados.",
  "Every chat with your notes agent": "Todos los chats con el agente de tus notas",
  "Every connected AI loses all {n} tools at once and can no longer read or change your notes until you turn tools back on here.": "Todas las IA conectadas pierden las {n} herramientas a la vez y ya no pueden leer ni cambiar tus notas hasta que vuelvas a activar las herramientas aquí.",
  "Every connected AI loses it at once. You can turn it back on any time.": "Todas las IA conectadas la pierden a la vez. Puedes volver a activarla cuando quieras.",
  "Every connected AI loses them at once. You can turn them back on any time.": "Todas las IA conectadas las pierden a la vez. Puedes volver a activarlas cuando quieras.",
  "Every connected agent loses its memory until Memora runs again.": "Todos los agentes conectados pierden su memoria hasta que Memora vuelva a funcionar.",
  "Every device on a home or office network, written as address/size: 192.168.1.0/24 covers 192.168.1.0 to 192.168.1.255.": "Todos los dispositivos de una red doméstica o de oficina, escritos como dirección/tamaño: 192.168.1.0/24 cubre de 192.168.1.0 a 192.168.1.255.",
  "Every device on a home or office network.": "Todos los dispositivos de una red doméstica o de oficina.",
  "Every image in the notes folder and where it is shown, and the pictures kept for Mnemo chats.": "Cada imagen de la carpeta de notas y dónde se muestra, y las imágenes guardadas para los chats de Mnemo.",
  "Every image is used in a note.": "Todas las imágenes se usan en una nota.",
  "Every note": "Todas las notas",
  "Every note and link, in 3D, as a graph or on a board.": "Cada nota y enlace, en 3D, como grafo o en un tablero.",
  "Every note and subfolder in \"{path}\" moves into {folder}; \"{name}\" is then removed. If a name is already taken there, a number is added to it.": "Cada nota y subcarpeta de \"{path}\" pasa a {folder}; después se elimina \"{name}\". Si un nombre ya está ocupado allí, se le añade un número.",
  "Every note becomes a card here, inside a frame for its folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Cada nota se convierte aquí en una tarjeta, dentro de un marco para su carpeta. La guía muestra cómo hacer que una IA guarde su conocimiento aquí, o cómo escribir una nota tú mismo.",
  "Every note becomes a point of light here, grouped by folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Cada nota se convierte aquí en un punto de luz, agrupado por carpeta. La guía muestra cómo hacer que una IA guarde su conocimiento aquí, o cómo escribir una nota tú mismo.",
  "Every note tagged #{tag} ({notes}) gets the new name, inline #tags in the text too.": "Cada nota con la etiqueta #{tag} ({notes}) recibe el nuevo nombre, también las #etiquetas dentro del texto.",
  "Every note tagged {tags} gets one tag instead ({notes}). Inline #tags in the text change too. There is no one-step undo; each note keeps its history.": "Cada nota con las etiquetas {tags} recibe una sola etiqueta ({notes}). Las #etiquetas dentro del texto también cambian. No se puede deshacer en un paso; cada nota conserva su historial.",
  "Every read and write by an agent shows up live, so you always know who did what.": "Cada lectura y escritura de un agente aparece en vivo, así siempre sabes quién hizo qué.",
  "Every request that reaches this rule is {verb}.": "Toda petición que llegue a esta regla es {verb}.",
  "Every request. Put it last, to catch whatever the rules above did not.": "Toda petición. Ponla al final, para atrapar lo que las reglas anteriores no cubrieron.",
  "Every setting and where it lives.": "Cada ajuste y dónde está.",
  "Every shortcut in the web UI.": "Cada atajo de la interfaz web.",
  "Every tag and its notes": "Cada etiqueta y sus notas",
  "Every tool agents can call": "Cada herramienta que pueden llamar los agentes",
