  "Font": "Fuente",
  "For": "Para",
  "For authentication choose <b>OAuth</b>, leave the client ID and secret empty, and click <b>Create</b>. A Memora page opens: press <b>Allow</b>.": "En autenticación elige <b>OAuth</b>, deja vacíos el ID de cliente y el secreto, y haz clic en <b>Crear</b>. Se abre una página de Memora: pulsa <b>Permitir</b>.",
  "For example: Product launch": "Por ejemplo: Lanzamiento del producto",
