  "From now on, whenever I tell you something important, save it into Memora. Try it now: save a note that I started using Memora today.": "A partir de ahora, cada vez que te cuente algo importante, guárdalo en Memora. Pruébalo ya: guarda una nota diciendo que hoy empecé a usar Memora.",
