  "Gathering the real activity for {range}. This can take a moment on a big log, please wait.": "Reuniendo la actividad real de {range}. Puede tardar un momento con un registro grande; espera, por favor.",
  "General": "General",
  "Get a one-time code on the server": "Obtén un código de un solo uso en el servidor",
  "Get started": "Empezar",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "Conóceme a través de mis notas. Revisa mi bóveda (notas recientes, diarios, proyectos, cualquier cosa sobre mí) y guarda lo que aprendas con remember_owner: quién soy, en qué trabajo, cómo me gustan las respuestas, qué me gusta. Solo cosas breves y duraderas, nunca secretos. Luego cuéntame en pocas líneas qué guardaste.",
  "Gets its own agent key: read and write nodes over MCP": "Recibe su propia clave de agente: lee y escribe nodos por MCP",
  "Getting started": "Primeros pasos",
  "GitHub answered HTTP {code}": "GitHub respondió HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "Dale a Claude, Cursor o cualquier app MCP su propia clave y deja que guarde lo que ya sabe de ti.",
  "Give a key read-only access, or let it write too.": "Da a una clave acceso de solo lectura, o permite que también escriba.",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "Dale a cada app o dispositivo su propio agente. Así Actividad muestra exactamente quién hizo qué, y puedes desactivar uno sin tocar los demás.",
