  "Import and export": "Importar y exportar",
  "Imported": "Importado",
  "In ChatGPT, open <b>Settings → Apps &amp; Connectors → Advanced settings</b> and turn on <b>Developer mode</b>. Then choose <b>Create</b>.": "En ChatGPT, abre <b>Settings → Apps &amp; Connectors → Advanced settings</b> y activa <b>Developer mode</b>. Luego elige <b>Create</b>.",
  "In Claude (web or desktop), open <b>Settings → Connectors</b> and choose <b>Add custom connector</b>.": "En Claude (web o escritorio), abre <b>Settings → Connectors</b> y elige <b>Add custom connector</b>.",
  "In Claude Desktop, open <b>Settings → Developer → Edit Config</b>. On newer versions, pick <b>Claude</b> instead.": "En Claude Desktop, abre <b>Settings → Developer → Edit Config</b>. En versiones más recientes, elige <b>Claude</b>.",
  "In Windsurf, open <b>Settings → Cascade → MCP servers</b> and choose <b>View raw config</b>.": "En Windsurf, abre <b>Settings → Cascade → MCP servers</b> y elige <b>View raw config</b>.",
