  "Internet (tunnel)": "Internet (túnel)",
  "Internet address (IP)": "Dirección de internet (IP)",
  "It becomes your first rule.": "Pasa a ser tu primera regla.",
  "It becomes {path}. Links to its notes keep working.": "Pasa a ser {path}. Los enlaces a sus notas siguen funcionando.",
  "It can change notes, but nothing lets it connect.": "Puede cambiar notas, pero nada le permite conectarse.",
  "It can search and read your notes, but not change them": "Puede buscar y leer tus notas, pero no cambiarlas",
  "It can search, read and save your notes": "Puede buscar, leer y guardar tus notas",
  "It can {list}.": "Puede {list}.",
  "It cannot do anything yet": "Aún no puede hacer nada",
  "It has full control: it reads and changes notes, and can manage Memora and other agents": "Tiene control total: lee y cambia notas, y puede gestionar Memora y otros agentes",
  "It holds {n} note. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Contiene {n} nota. A continuación eliges qué pasa con ella: moverla a otra carpeta o a la Papelera. Aún no se ha cambiado nada.",
  "It holds {n} notes. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Contiene {n} notas. A continuación eliges qué pasa con ellas: moverlas a otra carpeta o a la Papelera. Aún no se ha cambiado nada.",
  "It is added at the end, as rule {n}, so it is checked last.": "Se añade al final, como regla {n}, así que se comprueba la última.",
  "It is gone when you leave, pictures included. Changes to your notes still show in Activity and History.": "Desaparece al salir, imágenes incluidas. Los cambios en tus notas siguen apareciendo en Actividad e Historial.",
  "It is kept locked on the server. Enter your Memora password and the buttons below put it in for you.": "Se guarda bloqueada en el servidor. Introduce tu contraseña de Memora y los botones de abajo la ponen por ti.",
  "It is taking a while. Check the server, then reload this page.": "Está tardando. Revisa el servidor y recarga esta página.",
  "It leaves the Pinned list only; the folder itself stays where it is.": "Solo sale de la lista Fijados; la carpeta sigue donde está.",
  "It leaves the Pinned list only; the note itself stays where it is.": "Solo sale de la lista Fijados; la nota sigue donde está.",
  "It may have been renamed, moved or deleted. Deleted notes wait in the Trash.": "Puede haberse renombrado, movido o eliminado. Las notas eliminadas esperan en la Papelera.",
  "It moves; links to it are updated and pins follow.": "Se mueve; los enlaces a ella se actualizan y los fijados la siguen.",
  "It must sign in again and is told why": "Debe iniciar sesión de nuevo y se le avisa del motivo",
  "It prints a one-time code. This page moves on by itself.": "Muestra un código de un solo uso. Esta página avanza sola.",
  "It reached Memora but did not finish. It often works on the next try.": "Llegó a Memora pero no terminó. Suele funcionar al siguiente intento.",
  "It reached Memora but did not finish: {error} It often works on the next try.": "Llegó a Memora pero no terminó: {error} Suele funcionar al siguiente intento.",
  "It shows up under this name in Activity, the brain and the graph. Name it after the device when you use {app} in more than one place, like \"{example}\".": "Aparece con este nombre en Actividad, el cerebro y el grafo. Nómbralo según el dispositivo si usas {app} en más de un lugar, como \"{example}\".",
  "It was shown when it was made. Make a new key to see one again.": "Se mostró al crearla. Crea una clave nueva para ver una de nuevo.",
  "Italic": "Cursiva",
  "Its API key and its models are removed. Chats stay; a chat that used one of its models switches to the default.": "Se eliminan su clave de API y sus modelos. Los chats se quedan; un chat que usaba uno de sus modelos pasa al predeterminado.",
  "Its key and access stay the same in every notes folder. Connect another one any time.": "Su clave y acceso son los mismos en todas las carpetas de notas. Conecta otro cuando quieras.",
  "Its key is filled in on the next step": "Su clave se rellena en el siguiente paso",
  "Its key is refused until you turn it back on. Nothing is deleted.": "Su clave se rechaza hasta que la reactives. No se elimina nada.",
  "Its key is refused. Turn it on to let it connect again with the same key.": "Su clave se rechaza. Actívalo para que pueda conectarse de nuevo con la misma clave.",
  "Its key stopped working. You can restore it until you reload the app.": "Su clave dejó de funcionar. Puedes restaurarlo hasta que recargues la app.",
  "Its key stops working at once. Past activity stays; you can restore it until you reload the app.": "Su clave deja de funcionar al instante. La actividad pasada se queda; puedes restaurarlo hasta que recargues la app.",
  "Its key was shown only once, when it was made. A new key replaces it and the old one stops working at once.": "Su clave se mostró solo una vez, al crearla. Una clave nueva la reemplaza y la anterior deja de funcionar al instante.",
  "Its notes are in its folders. You can also start one here.": "Sus notas están en sus carpetas. También puedes empezar una aquí.",
  "Its numbers, timeline and export.": "Sus cifras, cronología y exportación.",
  "Its old folder is not known, so it goes to the top level": "Se desconoce su carpeta anterior, así que va al nivel superior",
  "Its page": "Su página",
  "Its page shows how to connect it.": "Su página muestra cómo conectarlo.",
  "Its page: status, recent calls, access and settings.": "Su página: estado, llamadas recientes, acceso y ajustes.",
  "Its permissions are a custom mix. Pick a level to replace them, or fine-tune them under Advanced.": "Sus permisos son una mezcla personalizada. Elige un nivel para reemplazarlos o ajústalos en Avanzado.",
