  "Long chats, light": "Chats largos, ligeros",
  "Long enough. A few more characters make it stronger.": "Suficientemente larga. Unos caracteres más la hacen más segura.",
  "Longer tasks show as a checklist above the message box: not started, in progress, done.": "Las tareas largas aparecen como una lista sobre el cuadro de mensaje: sin empezar, en curso, hecha.",
  "Longest sign-in": "Sesión más larga",
  "Longest sign-in must be at least the inactivity time": "La sesión más larga debe ser al menos el tiempo de inactividad",
  "Look for tags that mean the same thing": "Buscar etiquetas que signifiquen lo mismo",
  "Look through the project in this folder and save it into Memora: what it is for, how it is built, how to run it, technical decisions, and anything worth remembering. Make one note per topic, in a folder named after the project inside Projects.": "Revisa el proyecto de esta carpeta y guárdalo en Memora: para qué sirve, cómo está construido, cómo ejecutarlo, decisiones técnicas y todo lo que valga la pena recordar. Haz una nota por tema, en una carpeta con el nombre del proyecto dentro de Projects.",
