  "Medium": "Medio",
  "Medium text": "Texto mediano",
  "Meet Mnemo, your notes agent": "Conoce a Mnemo, tu agente de notas",
  "Memora address (MCP endpoint)": "Dirección de Memora (endpoint MCP)",
  "Memora already uses this folder.": "Memora ya usa esta carpeta.",
  "Memora by Codrihub Tech": "Memora de Codrihub Tech",
  "Memora can save notes here": "Memora puede guardar notas aquí",
  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Memora comprueba la carpeta y te pide confirmar antes de cambiar. No se mueve ni se copia nada, y puedes volver a la anterior aquí. ¿Usas Docker? Usa una carpeta montada en el contenedor.",
  "Memora could not start.": "Memora no pudo iniciarse.",
  "Memora data folder": "Carpeta de datos de Memora",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Memora comprueba primero que la carpeta nueva existe (o se puede crear) y que puede guardar notas en ella. Si la comprobación falla, no cambia nada.",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Memora comprueba primero que la carpeta nueva existe y que puede guardar notas en ella. Si la comprobación falla, no cambia nada.",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "Memora en tu idioma, Mnemo mostrando su plan mientras trabaja, y tú eligiendo lo que puede usar y ver.",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Memora es una app de notas que tus apps de IA también pueden usar. Tú escribes en ella, ellas leen y escriben las mismas notas, y siempre puedes ver qué cambió.",
  "Memora is free and open source": "Memora es libre y de código abierto",
  "Memora is free and open source. A star helps others find it.": "Memora es libre y de código abierto. Una estrella ayuda a que otros la encuentren.",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Memora es memoria avanzada: creada para recordar lo que tú y tu IA aprenden, y para recordar más cuanto más la usas.",
  "Memora is restarting": "Memora se está reiniciando",
  "Memora is shut down": "Memora está apagada",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Memora sigue vacía. Conecta una app de IA, envíale un prompt y guardará aquí lo que sabe de ti, como notas que puedes leer, editar y ver en el cerebro.",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Memora guarda una lista de tus etiquetas para sugerirlas mientras escribes. Actualízala si falta una etiqueta o está desfasada.",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "Memora conserva cada versión de una nota cuando la carpeta de la bóveda es un repositorio git. Ejecuta {cmd} una vez en la carpeta de la bóveda (consulta Configuración, «Historial de versiones» en la documentación); desde entonces cada cambio se guarda aquí.",
  "Memora keeps it in one place:": "Memora lo guarda en un solo lugar:",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Memora guarda cada nota como un archivo Markdown sencillo en la máquina donde se ejecuta. Nada queda atrapado: abre los archivos en cualquier editor, haz copias de seguridad o guárdalos en Git.",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Memora habla MCP sobre HTTP streamable. Las apps envían la clave en la cabecera <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Memora se detiene en la máquina donde se ejecuta. Tus notas siguen a salvo en el disco.",
  "Memora version": "Versión de Memora",
  "Memora v{latest} is available. This server runs v{current}.": "Memora v{latest} está disponible. Este servidor usa v{current}.",
  "Memora, open Overview": "Memora, abrir Resumen",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora: una bóveda de notas que alojas tú mismo, con un agente que la ordena.",
  "Memory used: {used} of {win}": "Memoria usada: {used} de {win}",
  "Mentioned in": "Mencionado en",
  "Mentions": "Menciones",
