  "Message to {mnemo}": "Mensaje para {mnemo}",
  "Messaged {agent}": "Escribió a {agent}",
  "Messages and the message box line up exactly in every width, the model picker has its own surface, the fleeting chat fits phones, and a question's options never slide away as you tap them.": "Los mensajes y el cuadro de mensaje se alinean exactamente en cualquier ancho, el selector de modelo tiene su propia superficie, el chat efímero cabe en el teléfono y las opciones de una pregunta ya no se mueven al tocarlas.",
  "Middle-drag": "Arrastre con botón central",
  "Midnight": "Medianoche",
  "Minimap": "Minimapa",
  "Minimap: click or drag to move the view": "Minimapa: haz clic o arrastra para mover la vista",
  "Mist": "Niebla",
  "Mnemo (AI agent)": "Mnemo (agente de IA)",
  "Mnemo and agents can do on a board everything you can, over MCP, behind four Kanban permission switches that follow Ask first, Auto and Read only.": "Mnemo y los agentes pueden hacer en un tablero todo lo que tú puedes, mediante MCP, tras cuatro interruptores de permisos de Kanban que siguen Preguntar antes, Auto y Solo lectura.",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "Botón de Mnemo oculto. Vuelve a mostrarlo desde Más, Mostrar el botón de Mnemo.",
  "Mnemo goes on without sub-agents": "Mnemo continúa sin subagentes",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "Mnemo aún no tiene modelo: añade un proveedor y sus modelos en Ajustes, Mnemo",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Mnemo viene integrado en Memora. Conecta tu propia clave de IA y pide lo que quieras con tus palabras: busca, escribe, etiqueta, enlaza y ordena notas por ti.",
  "Mnemo is still answering in this chat": "Mnemo sigue respondiendo en este chat",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Mnemo es el agente integrado en Memora. Conecta tu propia clave de IA y pide las cosas con palabras normales: mantiene tus notas en orden mientras tus otras apps las usan.",
  "Mnemo keeps at most {n} providers; delete one first": "Mnemo admite como máximo {n} proveedores; elimina uno primero",
  "Mnemo knows what is due": "Mnemo sabe qué vence",
  "Mnemo manages its sub-agents, keeps its plan with the chat, and the chat fits every screen better.": "Mnemo gestiona sus subagentes, guarda su plan con el chat, y el chat se adapta mejor a cada pantalla.",
  "Mnemo runs its sub-agents": "Mnemo dirige sus subagentes",
  "Mnemo stopped after {n} steps; say \"continue\" to go on.": "Mnemo se detuvo tras {n} pasos; di \"continúa\" para seguir.",
  "Mnemo's plan, live": "El plan de Mnemo, en vivo",
  "Mnemo's question sits on its own band, its answers below as rows to tap, as many as the question needs.": "La pregunta de Mnemo va en su propia franja y sus respuestas debajo como filas para tocar, tantas como necesite la pregunta.",
  "Mnemo, your notes agent": "Mnemo, tu agente de notas",
