  "Not created yet. Click to create it.": "Aún no creada. Haz clic para crearla.",
  "Not done": "No hecha",
  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "No se hizo: Mnemo está en modo Preguntar antes, así que los cambios esperan el visto bueno del propietario. Pregunta con ask_owner (di qué vas a cambiar; da una opción con approve: true como \"Sí, adelante\") y haz el cambio cuando apruebe.",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "No se hizo: Mnemo está en modo Solo lectura, así que las notas no se modifican. Di qué cambiarías; el propietario puede pasar a Preguntar antes o Auto en el chat.",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "No se hizo: el chat está en modo Preguntar antes, así que un subagente no puede modificar notas. Di en tu respuesta qué debería cambiar; Mnemo se lo pregunta al propietario.",
  "Not done: the owner switched {tool} off for Mnemo (Settings, Mnemo).": "No se hizo: el propietario desactivó {tool} para Mnemo (Ajustes, Mnemo).",
  "Not done: the owner switched {tool} off for sub-agents (Settings, Mnemo).": "No se hizo: el propietario desactivó {tool} para los subagentes (Ajustes, Mnemo).",
  "Not finished: the owner cut this reply before the tool returned.": "No terminó: el propietario cortó esta respuesta antes de que la herramienta devolviera el resultado.",
  "Not found": "No encontrado",
  "Not from AI apps": "No de apps de IA",
