  "Not started: \"{name}\" fits more than one model or none exactly. Close ones: {list}. Ask the owner which, or give the exact id.": "No se inició: \"{name}\" coincide con más de un modelo o con ninguno exacto. Cercanos: {list}. Pregunta al propietario cuál, o da el id exacto.",
  "Not started: there is no model \"{name}\" here. Tell the owner, or leave model out to use their default model.": "No se inició: aquí no hay ningún modelo \"{name}\". Díselo al propietario, o deja model sin indicar para usar su modelo predeterminado.",
  "Not sure it is on? Ask {app}: “{question}”": "¿No estás seguro de que esté activo? Pregunta a {app}: «{question}»",
