  "Notes": "Notas",
  "Notes and boards share one page frame with the same spacing on phones, tablets and desktops, and the links at the foot of a note share one tidy look that folds away.": "Notas y tableros comparten un mismo marco de página con el mismo espaciado en móviles, tabletas y ordenadores, y los enlaces al pie de una nota comparten un aspecto ordenado que se pliega.",
  "Notes and boards, connected": "Notas y tableros, conectados",
  "Notes and images in the notes folder.": "Notas e imágenes de la carpeta de notas.",
  "Notes and the links between them show up here as a map. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Las notas y los enlaces entre ellas aparecen aquí como un mapa. La guía muestra cómo hacer que una IA guarde su conocimiento aquí, o cómo escribir una nota tú mismo.",
  "Notes appear as the AI saves them and light up the brain. This page turns into your dashboard when the first note arrives.": "Las notas aparecen según la IA las guarda e iluminan el cerebro. Esta página se convierte en tu panel cuando llega la primera nota.",
  "Notes are not a password manager.": "Las notas no son un gestor de contraseñas.",
  "Notes changed in the app or in the folder": "Notas cambiadas en la app o en la carpeta",
  "Notes folder": "Carpeta de notas",
  "Notes folder switched": "Carpeta de notas cambiada",
  "Notes from {name}": "Notas de {name}",
  "Notes in the Obsidian Kanban format open as boards. Drag cards and lanes with a mouse or a finger, and every change lands in the note’s history.": "Las notas en formato Obsidian Kanban se abren como tableros. Arrastra tarjetas y columnas con el ratón o con el dedo, y cada cambio queda en el historial de la nota.",
  "Notes in the current folder are not moved, copied or deleted. You can switch back here at any time.": "Las notas de la carpeta actual no se mueven, copian ni eliminan. Puedes volver aquí en cualquier momento.",
  "Notes inside a folder": "Notas dentro de una carpeta",
  "Notes it found": "Notas que encontró",
  "Notes it saved": "Notas que guardó",
  "Notes must carry": "Las notas deben tener",
