  "Notes that carry at least one tag": "Notas con al menos una etiqueta",
  "Notes that carry every tag": "Notas con todas las etiquetas",
  "Notes that link nowhere and are linked from nowhere.": "Notas que no enlazan a ninguna parte y a las que nadie enlaza.",
  "Notes touched": "Notas tocadas",
  "Notes with a tag; the start of the tag is enough": "Notas con una etiqueta; basta con el inicio de la etiqueta",
  "Notes you delete wait here, so you can bring them back.": "Las notas que eliminas esperan aquí, para que puedas recuperarlas.",
  "Notes you or your AIs write show up here, newest first.": "Las notas que escribes tú o tus IA aparecen aquí, las más recientes primero.",
  "Notes, folders and images in this chat": "Notas, carpetas e imágenes de este chat",
  "Nothing deleted": "No se eliminó nada",
  "Nothing due this week": "Nada vence esta semana",
  "Nothing due today": "Nada vence hoy",
  "Nothing else in the last 24 hours.": "Nada más en las últimas 24 horas.",
  "Nothing from {name} in the last 24 hours.": "Nada de {name} en las últimas 24 horas.",
  "Nothing here": "Nada aquí",
  "Nothing hidden yet: tick the agents to hide it from. Right now all {n} agents can see it.": "Nada oculto aún: marca los agentes a los que ocultarlo. Ahora mismo los {n} agentes pueden verlo.",
  "Nothing hidden yet: tick the agents to hide it from. Right now the only agent can see it.": "Nada oculto aún: marca los agentes a los que ocultarlo. Ahora mismo el único agente puede verlo.",
  "Nothing in 24h": "Nada en 24 h",
  "Nothing in note names, folders or text, and nothing spelled close to it. Try fewer letters, another spelling, or a word from inside a note.": "Nada en nombres de notas, carpetas o texto, ni nada escrito parecido. Prueba con menos letras, otra ortografía o una palabra del interior de una nota.",
  "Nothing in the last 24 hours. What your AIs do shows up here as it happens.": "Nada en las últimas 24 horas. Lo que hacen tus IA aparece aquí según ocurre.",
  "Nothing in the log goes by “{name}”. Showing all activity.": "Nada en el registro se llama «{name}». Mostrando toda la actividad.",
  "Nothing in this range": "Nada en este intervalo",
