  "Nothing is allowed. Turn something on, or pause the agent instead.": "No se permite nada. Activa algo, o mejor pausa el agente.",
  "Nothing is lost: the current text stays in the history as v{n}, so you can switch back at any time.": "No se pierde nada: el texto actual queda en el historial como v{n}, así puedes volver en cualquier momento.",
  "Nothing links here yet.": "Nada enlaza aquí todavía.",
