  "Notifications": "Notificaciones",
  "Notifications are blocked for this site. Allow them in the browser settings, then try again.": "Las notificaciones están bloqueadas para este sitio. Permítelas en los ajustes del navegador y vuelve a intentarlo.",
  "Now": "Ahora",
