  "Off": "Desactivado",
  "Off for every AI.": "Desactivado para todas las IA.",
  "Off for every agent": "Desactivado para todos los agentes",
  "Off: its models are hidden in chats": "Desactivado: sus modelos se ocultan en los chats",
  "Off: tap to switch on": "Desactivado: toca para activar",
  "Offline": "Sin conexión",
  "Offline · Memora": "Sin conexión · Memora",
  "Offline, retrying": "Sin conexión, reintentando",
  "Older Gemini CLI without <code>gemini mcp add</code>: add the server to <code>~/.gemini/settings.json</code> under <code>mcpServers</code>, with <code>httpUrl</code> and the same header.": "Gemini CLI antiguo sin <code>gemini mcp add</code>: añade el servidor a <code>~/.gemini/settings.json</code> en <code>mcpServers</code>, con <code>httpUrl</code> y la misma cabecera.",
  "Older changes stay in History.": "Los cambios anteriores siguen en el Historial.",
  "Older messages were left out to fit the model's context.": "Los mensajes antiguos se omitieron para ajustarse al contexto del modelo.",
  "Older than 30 days": "Más de 30 días",
  "Older than 7 days": "Más de 7 días",
  "Older than 90 days": "Más de 90 días",
  "Older versions of a note: read, compare, restore, and the trash.": "Versiones anteriores de una nota: leer, comparar, restaurar, y la papelera.",
  "Oldest entry": "Entrada más antigua",
  "On": "Activado",
  "On a board": "En un tablero",
  "On desktop, drag the edge of the chat list or the side panel to make it wider or narrower. Each keeps a minimum and remembers its width.": "En el escritorio, arrastra el borde de la lista de chats o del panel lateral para ensancharlo o estrecharlo. Cada uno tiene un ancho mínimo y recuerda su ancho.",
  "On hover": "Al pasar el cursor",
  "On its avatar, its sparks in the brain and every activity row.": "En su avatar, sus destellos en el cerebro y cada fila de actividad.",
  "On the Boards page each board has a ⋯ menu to open, rename, move, duplicate, colour or trash it. Right-click or a long press opens it too.": "En la página de Tableros, cada tablero tiene un menú ⋯ para abrirlo, renombrarlo, moverlo, duplicarlo, colorearlo o enviarlo a la Papelera. También se abre con clic derecho o una pulsación larga.",
  "On this page": "En esta página",
  "On: tap to switch off": "Activado: toca para desactivar",
  "On: {mnemo} notes what it picks up in chats. Off: only what you add here. Saved at once.": "Activado: {mnemo} anota lo que capta en los chats. Desactivado: solo lo que añadas aquí. Se guarda al instante.",
  "Once installed, the app has its own icon, opens full screen and stays reachable when the network drops.": "Una vez instalada, la app tiene su propio icono, se abre a pantalla completa y sigue disponible cuando se cae la red.",
  "Once it is connected, paste this into a new chat in that app. It tells the AI to store what it knows into Memora.": "Cuando esté conectada, pega esto en un chat nuevo de esa app. Le indica a la IA que guarde lo que sabe en Memora.",
  "Once its app is set up, every call shows up here as it happens.": "Cuando su app esté configurada, cada llamada aparece aquí según ocurre.",
  "Once {name} is connected, everything it reads, writes and searches shows up here, live.": "Cuando {name} esté conectado, todo lo que lea, escriba y busque aparece aquí, en vivo.",
  "One address": "Una dirección",
  "One agent per app or device: its own key, its own name in Activity, turned off on its own.": "Un agente por app o dispositivo: su propia clave, su propio nombre en Actividad, desactivable por separado.",
  "One click": "Un clic",
  "One device or connection, such as 203.0.113.7. Searching \"what is my IP\" shows yours.": "Un dispositivo o conexión, como 203.0.113.7. Buscar \"cuál es mi IP\" muestra la tuya.",
  "One device or connection.": "Un dispositivo o conexión.",
  "One folder of notes that you and every connected AI share.": "Una carpeta de notas que compartís tú y todas las IA conectadas.",
  "One is hidden by the folder rule.": "Uno está oculto por la regla de la carpeta.",
  "One key per agent, its own permissions.": "Una clave por agente, con sus propios permisos.",
  "One last step": "Un último paso",
  "One memory every agent reads and writes, and you can see, edit and connect all of it.": "Una memoria que todos los agentes leen y escriben, y que puedes ver, editar y conectar por completo.",
  "One memory for every AI": "Una memoria para todas las IA",
  "One note shows this image; it will show as missing there. The version history keeps it.": "Una nota muestra esta imagen; allí aparecerá como faltante. El historial de versiones la conserva.",
  "One per line. They show among the suggestions on a new chat, marked Yours, and stay until you change them.": "Una por línea. Aparecen entre las sugerencias de un chat nuevo, marcadas como Tuyas, y se quedan hasta que las cambies.",
  "One private memory that you and your AI apps share, so nothing has to be explained twice.": "Una memoria privada que compartes con tus apps de IA, para no explicar nada dos veces.",
  "One set of notes for every AI app": "Un solo conjunto de notas para todas las apps de IA",
  "Online": "En línea",
  "Only PNG, JPEG, WebP and GIF images can be added": "Solo se pueden añadir imágenes PNG, JPEG, WebP y GIF",
  "Only in the current version": "Solo en la versión actual",
  "Only in version {n}": "Solo en la versión {n}",
  "Only letters, digits and - _ / . can be used.": "Solo se pueden usar letras, dígitos y - _ / .",
  "Only looks at notes; changes nothing.": "Solo mira las notas; no cambia nada.",
  "Only looks things up and never writes. For agents with a read-only key.": "Solo consulta y nunca escribe. Para agentes con una clave de solo lectura.",
  "Only pictures in your newest message go to the image model, and you hear of it in a short toast.": "Solo las imágenes de tu mensaje más reciente van al modelo de imagen, y te enteras con un aviso breve.",
  "Only reads and answers; never changes notes": "Solo lee y responde; nunca cambia notas",
  "Only the agents you pick. New agents can’t see it.": "Solo los agentes que elijas. Los agentes nuevos no pueden verlo.",
  "Only the first rule that fits a request counts.": "Solo cuenta la primera regla que encaja con una petición.",
  "Only the latest questions go on the page at first; earlier ones come in as you scroll up or jump to them on the timeline.": "Primero solo se cargan las preguntas más recientes; las anteriores llegan al desplazarte hacia arriba o saltar a ellas en la línea de tiempo.",
  "Only the ones I pick": "Solo los que yo elija",
