  "Past due dates show in a warning tint and today’s in a softer one, and the Boards page counts what is overdue. A board’s own date colours win.": "Las fechas vencidas se muestran con un tono de aviso y la de hoy con uno más suave, y la página de Tableros cuenta lo que está vencido. Los colores de fecha propios de un tablero tienen prioridad.",
  "Paste both into the app and save.": "Pega ambos en la app y guarda.",
  "Paste it in a terminal and press <kbd>Enter</kbd>, then start Codex in that same terminal.": "Pégalo en un terminal y pulsa <kbd>Enter</kbd>; luego inicia Codex en ese mismo terminal.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "Pégalo en un terminal y pulsa <kbd>Enter</kbd>. Luego inicia Claude Code, o reinícialo: Memora se carga sola.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Gemini CLI, or restart it, and type <code>/mcp</code> to see Memora.": "Pégalo en un terminal y pulsa <kbd>Enter</kbd>. Luego inicia Gemini CLI, o reinícialo, y escribe <code>/mcp</code> para ver Memora.",
  "Paste it into the app where it asks for a key.": "Pégala en la app donde pida una clave.",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "Pégalo en el archivo y guarda; luego pulsa <b>Refresh</b>. Memora aparece en la lista.",
  "Paste it into the file, save, and restart Claude Desktop. It needs Node.js on this computer.": "Pégalo en el archivo, guarda y reinicia Claude Desktop. Necesita Node.js en este ordenador.",
