  "Save into Memora what I've shared with you about my personal life: my interests, habits, goals, the people who matter to me and things I care about. Put these notes in a folder named Private, one note per topic, and link related notes. Never save passwords, card numbers or other secrets. When you're done, tell me what you saved.": "Guarda en Memora lo que te he contado sobre mi vida personal: mis intereses, hábitos, metas, las personas importantes para mí y las cosas que me importan. Pon estas notas en una carpeta llamada Private, una nota por tema, y enlaza las notas relacionadas. Nunca guardes contraseñas, números de tarjeta ni otros secretos. Al terminar, dime qué guardaste.",
  "Save into Memora what you know about my work: my role, my team, the projects I'm on and where they stand, and decisions we made. Make one note per project or topic and link them together.": "Guarda en Memora lo que sabes sobre mi trabajo: mi puesto, mi equipo, los proyectos en los que estoy y cómo van, y las decisiones que tomamos. Haz una nota por proyecto o tema y enlázalas entre sí.",
