  "This note is removed from the vault for good, with its text, tags and links. Every earlier version is erased from the version history too, so no one, agents included, can read it again.": "Esta nota se elimina de la bóveda para siempre, con su texto, etiquetas y enlaces. Cada versión anterior también se borra del historial de versiones, así que nadie, ni siquiera los agentes, podrá leerla de nuevo.",
