  "This server is run by systemd, which starts it again a few seconds later. To keep it stopped, run {cmd} on the server instead.": "Este servidor lo gestiona systemd, que lo inicia de nuevo unos segundos después. Para mantenerlo detenido, ejecuta {cmd} en el servidor.",
  "This server runs in Docker, which may start it again. To keep it stopped, run {cmd} on the host instead.": "Este servidor se ejecuta en Docker, que puede iniciarlo de nuevo. Para mantenerlo detenido, ejecuta {cmd} en el host.",
