  "When": "Cuándo",
  "When a chat's model fails (the provider is down, busy or out of credit), {mnemo} carries on with these, in this order, up to five. With none left, the chat shows the error and Try again. Saved at once.": "Cuando falla el modelo de un chat (el proveedor está caído, ocupado o sin crédito), {mnemo} continúa con estos, en este orden, hasta cinco. Si no queda ninguno, el chat muestra el error y Reintentar. Se guarda al instante.",
