  "{mnemo} asks this model when you want a picture made.": "{mnemo} le pide a este modelo que cree una imagen cuando quieres una.",
  "{mnemo} button hidden. Bring it back from More, Show the {mnemo} button.": "Botón de {mnemo} oculto. Recupéralo desde Más, Mostrar el botón de {mnemo}.",
  "{mnemo} button hidden. Show it again here or from More.": "Botón de {mnemo} oculto. Vuelve a mostrarlo aquí o desde Más.",
