  "{mnemo} may learn about you": "{mnemo} puede aprender sobre ti",
  "{mnemo} only works in your notes. Each change shows in Activity and can be undone from History.": "{mnemo} solo trabaja en tus notas. Cada cambio aparece en Actividad y se puede deshacer desde Historial.",
  "{mnemo} reads your vault in a new chat and keeps what it learns here.": "{mnemo} lee tu bóveda en un chat nuevo y guarda aquí lo que aprende.",
  "{mnemo} settings saved": "Ajustes de {mnemo} guardados",
  "{mnemo} settings: models and keys": "Ajustes de {mnemo}: modelos y claves",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "{mnemo} inicia subagentes por sí solo cuando una tarea se divide bien; no hay nada que configurar. Se ejecutan con tu modelo predeterminado y luego los de respaldo, salvo que nombres un modelo en el chat. Síguelos y cambia su modelo en Agentes, arriba a la derecha del chat. Usan tokens propios, así que en Preguntar antes {mnemo} pregunta y dice cuántos aproximadamente; en Auto simplemente se ejecutan. Se guarda al instante.",
  "{mnemo} stopped it": "{mnemo} lo detuvo",
  "{mnemo} will keep that in mind": "{mnemo} lo tendrá en cuenta",
  "{mnemo} writes new suggestions from your recent notes (yours stay)": "{mnemo} escribe sugerencias nuevas a partir de tus notas recientes (las tuyas se quedan)",
  "{mnemo}'s own ({n})": "Propias de {mnemo} ({n})",
  "{mnemo}'s own notes on how to talk to you, read in every chat. Click one to change it.": "Las notas propias de {mnemo} sobre cómo hablarte, que lee en cada chat. Haz clic en una para cambiarla.",
