  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "{model} no puede ver imágenes; recibió sus nombres. Configura un modelo que lea imágenes en Ajustes para que las vea.",
  "{model} cannot look at images; the image model described them for it.": "{model} no puede ver imágenes; el modelo de imágenes las describió por él.",
  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} no puede leer imágenes, así que solo recibe sus nombres. Configura un modelo que lea imágenes o cambia el modelo de este chat.",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} no puede leer imágenes, así que solo recibió sus nombres. Configura un modelo que lea imágenes o cambia el modelo de este chat.",
